const cfg   = $('Config').first().json;
const kws   = $('Keywords').first().json.keywords;
const rs    = $('Read Sheet').first().json;
const hist  = rs.__history || { byRow: {}, monthKeys: [] };
const tasks = $('Build Tasks').all();
const collect = $('Collect Results').first().json || {};

const periods = (tasks[0] && tasks[0].json.__periods) || [];
const noFetch = !!(tasks[0] && tasks[0].json.__noFetch);

// ---------- 1) الربط: السحبة الأولى ثم المحاولة التانية ----------
const cells = {};                       // taskId → classify()
const pairing = { pass1: null, pass2: null };

if (!noFetch) {
  const p1 = pairResults(tasks, $('GSC Query').all(), cfg.gscRowLimit);
  pairing.pass1 = p1.stats;
  Object.keys(p1.map).forEach(k => { cells[k] = p1.map[k]; });

  // نود GSC Retry Query بيشتغل بس لما يبقى فيه طلبات محتاجة إعادة.
  if (Number(collect.retryCount) > 0) {
    const retryTasks = $('Collect Results').all();
    const p2 = pairResults(retryTasks, $('GSC Retry Query').all(), cfg.gscRowLimit);
    pairing.pass2 = p2.stats;
    Object.keys(p2.map).forEach(k => {
      // المحاولة التانية بتستبدل نتيجة فاشلة بس — مش بتلغي نتيجة سليمة.
      if (!cells[k] || cells[k].state !== 'ok') cells[k] = p2.map[k];
    });
  }
}

// ---------- 2) قراءة كل خانة ----------
const fresh = {};
const requestStats = { requested: tasks.length, ranked: 0, noData: 0, failed: 0, truncated: 0,
                       scopePage: 0, scopeSite: 0 };
const failures = [];      // تفاصيل كل خانة فشلت
const pageMisses = [];    // الصفحة المستهدفة متحطة بس مكانتش ظاهرة الفترة دي
const noPageKws = {};     // كلمات من غير رابط صفحة مستهدفة أصلاً

// ---- شهادة الرابط: هل الصفحة المستهدفة ظهرت عند جوجل ولا لأ؟ ----
// الفحص ده مجاني: بيستخدم نفس الردود اللي سحبناها. وبيفرّق بين حالتين
// بيدّوا نفس الخانة الفاضية ومعناهم مختلف تمامًا:
//   • الكلمة مالهاش ترتيب أصلاً        → الرقم صح، الصفحة لسه ما ظهرتش
//   • الكلمة ليها ترتيب بصفحات تانية    → الرابط اللي عندنا غالبًا غلط
// التانية دي بتخلي التقرير يقول "مفيش ظهور" لصفحة شغالة فعلًا — رقم غلط
// بيعدّي من غير ما حد يشك فيه، لأن الرابط بيفتح عادي لما تجربه بإيدك.
const pageEvidence = {};  // keyword → { periods, seen, queryRanked, samples }
function noteEvidence(j, cell) {
  const e = pageEvidence[j.keyword] || (pageEvidence[j.keyword] = {
    keyword: j.keyword, page: j.page || '', periods: 0, seen: 0,
    queryRanked: 0, samples: [],
  });
  if (!j.page) return;
  if (cell.verdict === 'failed') return;      // فشل السحب مش شهادة على الرابط
  e.periods++;
  if (cell.pageFound) { e.seen++; return; }
  if (cell.pagesSeen > 0) {
    e.queryRanked++;
    if (e.samples.length < 3 && cell.topPage) {
      e.samples.push({ period: j.period, topPage: cell.topPage, position: cell.topPagePosition });
    }
  }
}

if (!noFetch) {
  tasks.forEach(t => {
    const j = t.json || {};
    if (!j.taskId) return;
    const cell = readCell(cells[j.taskId], j.page, cfg.pageMatch);
    fresh[j.taskId] = cell;
    noteEvidence(j, cell);
    if (!j.page) noPageKws[j.keyword] = 1;
    if (cell.verdict === 'ranked') {
      requestStats.ranked++;
      if (cell.truncated) requestStats.truncated++;
      if (cell.scope === 'page') requestStats.scopePage++; else requestStats.scopeSite++;
      if (j.page && cell.matchMode === 'site-fallback' && pageMisses.length < 200) {
        pageMisses.push({ keyword: j.keyword, period: j.period,
                          expected: j.page, topPage: cell.topPage,
                          pagesSeen: cell.pagesSeen });
      }
    } else if (cell.verdict === 'no-data') {
      requestStats.noData++;
    } else {
      requestStats.failed++;
      if (failures.length < 200) {
        failures.push({ keyword: j.keyword, country: j.countryName,
                        period: j.period, reason: cell.reason });
      }
    }
  });
}

// ---------- 2b) حكم على كل رابط ----------
const pageAudit = { ok: [], suspect: [], notRanking: [], unchecked: [] };
Object.keys(pageEvidence).forEach(function (kw) {
  const e = pageEvidence[kw];
  if (!e.periods)        { pageAudit.unchecked.push(e); return; }
  if (e.seen > 0)        { pageAudit.ok.push(e); return; }
  // الصفحة ما ظهرتش ولا مرة، لكن الكلمة ليها ترتيب بصفحات تانية → شبهة رابط
  if (e.queryRanked > 0) { pageAudit.suspect.push(e); return; }
  pageAudit.notRanking.push(e);
});

// ---------- 3) الأعمدة: كل اللي في الشيت + أي عمود جديد ----------
const allKeysSet = {};
(hist.monthKeys || []).forEach(k => { allKeysSet[k] = true; });
periods.forEach(p => { allKeysSet[p.key] = true; });
const allKeys = Object.keys(allKeysSet).sort();

// الأعمدة اللي لسه بياناتها ممكن تتغير عند جوجل (آخر VOLATILE_TAIL عمود).
// أي عمود أقدم من كده بياناته مقفولة، فلو السحبة رجعت "مفيش" والأرشيف فيه
// رقم → الأرشيف هو الصح والسحبة هي اللي فيها مشكلة.
const volatile = {};
periods.slice(Math.max(0, periods.length - (cfg.volatileTail || 2))).forEach(p => { volatile[p.key] = true; });

const AR_MON = ['يناير','فبراير','مارس','أبريل','مايو','يونيو',
                'يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
// تسمية العمود بتختلف حسب الإيقاع: الشهري بيسمّي الشهر بالعربي،
// والأسبوعي بيستخدم التسمية اللي بناها Build Tasks (أسبوع كذا).
const __cadence = cfg.cadence;
const labelOf = (key) => __cadence === 'weekly'
  ? String(key)
  : (AR_MON[Number(String(key).split('-')[1]) - 1] || String(key));
const lastLabelOf = (p) => __cadence === 'weekly' ? (p.label || String(p.key)) : labelOf(p.key);

// ---------- 4) بناء الصفوف ----------
const data = [];        // للتقرير (آخر COLUMNS عمود)
const sheetRows = [];   // للشيت (كل الأعمدة من أول يوم)
const tally = { ranked: 0, noData: 0, fromArchive: 0, keptArchive: 0, holes: 0, archiveOnly: 0 };
const suspicious = [];  // خانات مسكنا فيها الأرشيف رغم إن السحبة قالت "مفيش"

function resolve(rowKey, key, isReportPeriod) {
  const f = fresh[rowKey + '||' + key];
  const o = (hist.byRow[rowKey] || {})[key];
  const archived = o && o.filled;
  const archivedNum = archived && o.position !== null;

  if (f && f.verdict === 'ranked') {
    return { state: 'ranked', position: f.position, impressions: f.impressions,
             cell: f.position, scope: f.scope, matchedPage: f.matchedPage || '' };
  }
  if (f && f.verdict === 'no-data') {
    // عمود قديم + الأرشيف فيه رقم → نمسك الأرشيف ونسجّل شبهة.
    if (archivedNum && !volatile[key]) {
      if (isReportPeriod && suspicious.length < 200) suspicious.push({ rowKey, period: key, archived: o.position });
      return { state: 'kept-archive', position: o.position, impressions: o.impressions, cell: o.position };
    }
    return { state: 'no-data', position: null, impressions: 0, cell: '-' };
  }
  // السحبة فشلت أو مفيش سحبة أصلاً → الأرشيف لو موجود، وإلا خانة فاضية.
  if (archived) {
    return { state: f ? 'from-archive' : 'archive-only',
             position: o.position, impressions: o.impressions,
             cell: o.position === null ? '-' : o.position };
  }
  return { state: 'hole', position: null, impressions: 0, cell: '' };
}

cfg.countries.forEach(c => {
  kws.forEach(k => {
    const rowKey = c.name + '||' + k.keyword;

    // --- الصف الكامل لكل الأعمدة (بيتكتب في الشيت زي ما هو) ---
    const cellsAll = [], imprAll = [];
    allKeys.forEach(mk => {
      const r = resolve(rowKey, mk, false);
      cellsAll.push(r.cell);
      imprAll.push(r.state === 'hole' ? '' : r.impressions);
    });
    sheetRows.push({ country: c.name, section: k.group, keyword: k.keyword,
                     page: k.page || '', article: k.article || '', cellsAll, imprAll });

    // --- أعمدة التقرير بس (السلايدز + الإيميل) ---
    const positions = [], impressions = [], cellsPos = [];
    periods.forEach(p => {
      const r = resolve(rowKey, p.key, true);
      if (r.state === 'ranked')            tally.ranked++;
      else if (r.state === 'no-data')      tally.noData++;
      else if (r.state === 'from-archive') tally.fromArchive++;
      else if (r.state === 'kept-archive') tally.keptArchive++;
      else if (r.state === 'archive-only') tally.archiveOnly++;
      else                                 tally.holes++;
      positions.push(r.position);
      impressions.push(r.impressions || 0);
      cellsPos.push(r.state === 'hole' ? '' : r.cell);
    });

    const li = periods.length - 1;
    const lastCell = periods.length ? fresh[rowKey + '||' + periods[li].key] : null;
    data.push({
      country: c.name, section: k.group, group: k.group + ' — ' + c.name,
      keyword: k.keyword, page: k.page || '', article: k.article || '',
      sv: (k.sv === undefined || k.sv === null) ? '' : k.sv,
      positions, impressionsAll: impressions, cellsPos,
      impressions: impressions[li] || 0,
      // نطاق قياس آخر عمود: 'page' = الصفحة المستهدفة | 'site' = كل صفحات
      // الموقع للكلمة. بيتعرض في السلايد عشان اللي بيراجع يعرف يفلتر نفس
      // الفلتر في واجهة Search Console.
      scope: (lastCell && lastCell.scope) || (k.page ? 'page' : 'site'),
      matchedPage: (lastCell && lastCell.matchedPage) || '',
    });
  });
});

const safe = v => (typeof v === 'number' && !isFinite(v)) ? '' : v;
sheetRows.forEach(r => { r.cellsAll = r.cellsAll.map(safe); r.imprAll = r.imprAll.map(safe); });

const totalCells = data.length * periods.length;
const filled = tally.ranked + tally.noData + tally.fromArchive + tally.keptArchive + tally.archiveOnly;

return [{ json: {
  // الشهري ما عندوش startDate/endDate على الفترة، فبيتساب undefined ومحدش
  // بيقراه — والأسبوعي محتاجهم لبناء عنوان الأسبوع بالعربي.
  months: periods.map(p => ({ key: p.key, label: __cadence === 'weekly' ? p.label : labelOf(p.key),
                              caption: p.caption, year: p.year,
                              startDate: p.startDate, endDate: p.endDate })),
  data,
  allMonths: allKeys.map(k => ({ key: k, label: labelOf(k) })),
  sheetRows,
  lastMonth: periods.length ? lastLabelOf(periods[periods.length - 1]) : null,
  quality: {
    totalCells, filled,
    coverage: totalCells ? Math.round((filled / totalCells) * 10000) / 10000 : 1,
    tally, requestStats, pairing,
    failures, suspicious, pageMisses,
    keywordsWithoutPage: Object.keys(noPageKws),
    pageAudit: {
      ok: pageAudit.ok.length,
      notRanking: pageAudit.notRanking.map(function (e) { return e.keyword; }),
      suspect: pageAudit.suspect.map(function (e) {
        return { keyword: e.keyword, page: e.page, periodsRanked: e.queryRanked,
                 periods: e.periods, samples: e.samples };
      }),
    },
    noFetch,
    sheetError: rs.__sheetError || '',
    extent: rs.__extent || { rows: 0, cols: 0 },
    latestDataDate: (tasks[0] && tasks[0].json.__latestDataDate) || '',
    freshnessSource: $('Freshness Guard').first().json.freshnessSource,
    periodsInSheet: (hist.monthKeys || []).length,
    totalPeriodsStored: allKeys.length,
    keywordCount: kws.length,
    invalidEmails: cfg.mailInvalid || [],
  },
} }];

// بوابة جودة البيانات — آخر خط دفاع قبل ما نلمس الشيت أو نبني التقرير.
//
// بتقرر: نكمل ولا نوقف؟ وبتبني كمان مصفوفة القيم اللي هتتكتب في الشيت
// مبطّنة لآخر مقاس كان للشيت، عشان أي أعمدة/صفوف قديمة زايدة تتمسح ومايفضلش
// في الشيت بقايا من قايمة كلمات قديمة.
const cfg = $('Config').first().json;
const res = $input.first().json;
const q   = res.quality || {};

const problems = [];   // أسباب توقف الرن
const warnings = [];   // ملاحظات بتوصل في الإيميل ومابتوقفش الرن

// --- 1) الشيت نفسه ---
if (q.sheetError) {
  problems.push('مقدرناش نقرا الشيت: ' + q.sheetError +
                ' — الكتابة اتوقفت عشان ما نمسحش الأرشيف.');
}

// --- 2) سلامة الربط بين الطلبات والردود ---
const p1 = q.pairing && q.pairing.pass1;
if (p1 && p1.strict) {
  warnings.push('عدد ردود جوجل (' + p1.results + ') مش مساوي عدد الطلبات (' +
                p1.tasks + ') — اتعامل معاها بالربط المؤكد (pairedItem).');
}
if (p1 && p1.unpaired > 0) {
  warnings.push(p1.unpaired + ' رد من جوجل مقدرناش نربطه بطلبه واتجاهل.');
}

// --- 3) التغطية ---
const coverage = Number(q.coverage || 0);
const holes    = Number((q.tally || {}).holes || 0);
const minCov   = Number(cfg.minCoverage);
if (!q.noFetch && coverage < minCov) {
  problems.push('نسبة الخانات المكتملة ' + Math.round(coverage * 1000) / 10 +
                '% وأقل حد مسموح ' + Math.round(minCov * 1000) / 10 + '%.');
}
if (!q.noFetch && holes > Number(cfg.maxHoles)) {
  problems.push('عدد الخانات الفاضية ' + holes + ' وأقصى حد مسموح ' + cfg.maxHoles + '.');
}

// --- 4) أعمدة التقرير ---
const months = res.months || [];
if (!months.length) problems.push('مفيش ولا عمود في التقرير.');
if (months.length < Number(cfg.columns)) {
  warnings.push('التقرير فيه ' + months.length + ' عمود بس بدل ' + cfg.columns +
                ' — عادي لو الشيت لسه جديد أو بيانات جوجل ناقصة.');
}

// --- 5) صحة الأرقام نفسها ---
const badNumbers = [];
(res.data || []).forEach(d => {
  d.positions.forEach((p, i) => {
    if (p === null) return;
    if (!(p > 0) || p > 1000 || !isFinite(p)) {
      badNumbers.push(d.keyword + ' / ' + ((months[i] || {}).key || i) + ' = ' + p);
    }
  });
  (d.impressionsAll || []).forEach((v, i) => {
    if (v !== '' && (!isFinite(v) || v < 0)) {
      badNumbers.push(d.keyword + ' / ظهور ' + ((months[i] || {}).key || i) + ' = ' + v);
    }
  });
});
if (badNumbers.length) {
  problems.push('فيه ' + badNumbers.length + ' رقم خارج المدى المنطقي: ' +
                badNumbers.slice(0, 5).join(' | '));
}

// --- 6) عدد الصفوف ---
const expectedRows = (cfg.countries || []).length * Number(q.keywordCount || 0);
if ((res.data || []).length !== expectedRows) {
  problems.push('عدد صفوف التقرير ' + (res.data || []).length +
                ' والمتوقع ' + expectedRows + '.');
}

// --- 7) ملاحظات مش موقّفة ---
if ((q.tally || {}).keptArchive > 0) {
  warnings.push((q.tally.keptArchive) + ' خانة قديمة رجعت من جوجل "مفيش ظهور" ' +
                'رغم إن الأرشيف فيها رقم — مسكنا رقم الأرشيف لأن بيانات الشهور ' +
                'المقفولة مابتتغيرش.');
}
if ((q.pageMisses || []).length) {
  warnings.push((q.pageMisses.length) + ' خانة الصفحة المستهدفة فيها مكانتش ظاهرة، ' +
                'فالرقم اتحسب على مستوى الموقع كله للكلمة (زي فلتر الكلمة لوحدها ' +
                'في واجهة Search Console) — مش من صفحة تانية.');
}
// --- فحص الروابط الفعلي (نود Check Target Pages) ---
// ده بيمسك الرابط اللي بيعمل تحويل أو مكسور **قبل** ما جوجل يتسأل عنه أصلًا.
let pageCheck = { problems: [], tally: {}, networkBlocked: false, checked: 0 };
try { pageCheck = $('Page Check Report').first().json.pageCheck || pageCheck; } catch (e) { /* نود مش موجود */ }
if (pageCheck.networkBlocked) {
  warnings.push('مقدرناش نفحص روابط الصفحات من السيرفر (كل الطلبات اترفضت) — ' +
                'النتيجة اتجاهلت بدل ما نعلن روابط سليمة "مكسورة". راجع خروج n8n للإنترنت.');
} else if ((pageCheck.problems || []).length) {
  const byVerdict = {};
  pageCheck.problems.forEach(function (x) { (byVerdict[x.verdict] = byVerdict[x.verdict] || []).push(x); });
  const label = { redirected: 'بيعمل تحويل', canonical: 'كانوني مختلف',
                  broken: 'مكسور', 'server-error': 'خطأ سيرفر', unreachable: 'مش راجع' };
  Object.keys(byVerdict).forEach(function (v) {
    const list = byVerdict[v];
    warnings.push(list.length + ' رابط ' + (label[v] || v) + ' — فلتر الصفحة في Search Console ' +
      'مش هيطابقه فالخانة هتطلع "مفيش ظهور" وهي غلط. ' +
      list.slice(0, 4).map(function (x) { return x.keyword + ' → ' + (x.suggested || x.note); }).join(' | ') +
      (list.length > 4 ? ' …' : ''));
  });
}

// --- شهادة الروابط من جوجل نفسه: رابط غلط بيطلّع "مفيش ظهور" لصفحة شغالة ---
// دي مش ملاحظة تجميلية: الكلمة اللي ليها ترتيب بصفحات تانية والصفحة
// المستهدفة ما ظهرتش ولا مرة في كل الفترات معناها إن الرابط اللي عندنا
// مش الرابط اللي جوجل بيسجّله. الرقم اللي بيتبعت للعميل ساعتها '-' وهو غلط.
const pa = q.pageAudit || {};
const suspect = pa.suspect || [];
if (suspect.length) {
  warnings.push(suspect.length + ' كلمة صفحتها المستهدفة ما ظهرتش عند جوجل ولا مرة ' +
    'رغم إن الكلمة نفسها ليها ترتيب بصفحات تانية — يعني الرابط في ملف الكلمات ' +
    'غالبًا مش الرابط الكانوني اللي جوجل مسجّله، والخانة بتطلع "مفيش ظهور" وهي غلط. ' +
    'راجع: ' + suspect.slice(0, 6).map(function (x) {
      const sample = (x.samples || [])[0];
      return x.keyword + (sample ? ' (جوجل شايف: ' + sample.topPage + ')' : '');
    }).join(' | ') + (suspect.length > 6 ? ' …' : ''));
}
if ((pa.notRanking || []).length) {
  warnings.push((pa.notRanking || []).length + ' كلمة مالهاش ولا ظهور واحد في أي فترة — ' +
    'الرقم "مفيش ظهور" صح فيها، الصفحة لسه ما دخلتش نتائج البحث.');
}

const noPage = q.keywordsWithoutPage || [];
if (noPage.length) {
  warnings.push(noPage.length + ' كلمة من غير رابط صفحة مستهدفة، فأرقامها على مستوى ' +
                'الموقع كله. لو عايز الرقم يطابق فلتر Query + Page في الواجهة، حط ' +
                'الرابط في ملف الإكسل وأعِد التوليد: ' +
                noPage.slice(0, 8).join(' | ') + (noPage.length > 8 ? ' …' : ''));
}
if ((q.requestStats || {}).truncated > 0) {
  warnings.push(q.requestStats.truncated + ' كلمة رجع فيها عدد صفحات على الحد الأقصى (' +
                cfg.gscRowLimit + ') — يعني فيه صفحات اتقصّت ومجموع الظهور ناقص. ' +
                'ارفع GSC_ROW_LIMIT.');
}
if ((q.invalidEmails || []).length) {
  warnings.push('إيميلات بصيغة غلط واتجاهلت: ' + q.invalidEmails.join(', '));
}
if (q.freshnessSource !== 'gsc') {
  warnings.push('مقدرناش نسأل جوجل عن آخر يوم فيه بيانات، فاستخدمنا LAG_DAYS الاحتياطي.');
}

// --- 8) بناء قيم الشيت مبطّنة لآخر مقاس ---
const header = ['Country', 'Section', 'Keyword', 'Page', 'Article']
  .concat((res.allMonths || []).reduce((a, m) => a.concat([m.key + ' Pos', m.key + ' Impr']), []));

const body = (res.sheetRows || []).map(d =>
  [d.country, d.section, d.keyword, d.page, d.article]
    .concat(d.cellsAll.reduce((a, p, i) => a.concat([p, d.imprAll[i]]), [])));

const values = [header].concat(body);
const oldRows = Number((q.extent || {}).rows || 0);
const oldCols = Number((q.extent || {}).cols || 0);
const width   = Math.max(header.length, oldCols);
values.forEach(r => { while (r.length < width) r.push(''); });
while (values.length < oldRows) values.push(new Array(width).fill(''));

const ok = problems.length === 0;

// --- 9) نص التنبيه لو الرن اتوقف ---
const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const li  = arr => arr.map(t => '<li style="margin:0 0 6px 0;">' + esc(t) + '</li>').join('');

const failLines = (q.failures || []).slice(0, 40)
  .map(f => f.keyword + ' — ' + f.period + ' — ' + f.reason);
const failMore = Math.max(0, (q.failures || []).length - failLines.length);

const alertSubject = 'وقفنا تقرير SEO — ' + cfg.company + ' — البيانات مش مكتملة';

const alertText = [
  'الأوتوميشن اشتغل بس البيانات اللي رجعت من Google Search Console مش مكتملة،',
  'فوقفنا قبل ما نكتب على الشيت أو نبني التقرير — عشان ما نطلّعش أرقام ناقصة',
  'وما نمسحش الأرشيف.',
  '',
  'أسباب التوقف:',
].concat(problems.map(t => '- ' + t))
 .concat(warnings.length ? [''].concat(['ملاحظات:']).concat(warnings.map(t => '- ' + t)) : [])
 .concat(['', 'ملخص السحبة: ' +
   'طلبات ' + ((q.requestStats || {}).requested || 0) + ' | ' +
   'رجع بترتيب ' + ((q.requestStats || {}).ranked || 0) + ' | ' +
   'مفيش ظهور ' + ((q.requestStats || {}).noData || 0) + ' | ' +
   'فشل ' + ((q.requestStats || {}).failed || 0)])
 .concat(failLines.length ? ['', 'أول ' + failLines.length + ' خانة فشلت:'].concat(failLines.map(t => '- ' + t)) : [])
 .concat(failMore ? ['... و' + failMore + ' خانة كمان.'] : [])
 .concat(['', 'مفيش أي حاجة اتغيرت في الشيت ولا في العرض التقديمي.',
          'الرن الجاي هيعيد يسحب كل حاجة من أول وجديد.'])
 .join('\n');

const alertHtml =
'<div style="font-family:Calibri,Arial,sans-serif;direction:rtl;text-align:right;background:#f2f1ee;padding:24px;color:#142f38;font-size:14px;">' +
'<div style="max-width:700px;margin:0 auto;background:#ffffff;border:1px solid #d8d6d0;border-radius:10px;padding:22px;">' +
'<h3 style="margin:0 0 12px 0;font-size:16px;">تقرير SEO اتوقف — البيانات مش مكتملة</h3>' +
'<p style="line-height:1.9;margin:0 0 14px 0;">الأوتوميشن اشتغل بس البيانات اللي رجعت من Google Search Console مش مكتملة، ' +
'فوقفنا قبل ما نكتب على الشيت أو نبني التقرير. <b>الشيت والعرض التقديمي ما اتلمسوش خالص.</b></p>' +
'<div style="background:#f2f1ee;border:1px solid #d8d6d0;border-radius:6px;padding:12px 16px;margin-bottom:14px;">' +
'<b>أسباب التوقف</b><ul style="margin:8px 0 0 0;padding-inline-start:18px;line-height:1.8;">' + li(problems) + '</ul></div>' +
(warnings.length ? '<div style="border:1px solid #d8d6d0;border-radius:6px;padding:12px 16px;margin-bottom:14px;">' +
  '<b>ملاحظات</b><ul style="margin:8px 0 0 0;padding-inline-start:18px;line-height:1.8;">' + li(warnings) + '</ul></div>' : '') +
'<p style="margin:0 0 6px 0;"><b>ملخص السحبة:</b> طلبات ' + ((q.requestStats || {}).requested || 0) +
' • رجع بترتيب ' + ((q.requestStats || {}).ranked || 0) +
' • مفيش ظهور ' + ((q.requestStats || {}).noData || 0) +
' • فشل ' + ((q.requestStats || {}).failed || 0) + '</p>' +
'<p style="margin:0 0 14px 0;"><b>آخر يوم فيه بيانات عند جوجل:</b> ' + esc(q.latestDataDate || '—') + '</p>' +
(failLines.length ? '<div style="border:1px solid #d8d6d0;border-radius:6px;padding:12px 16px;">' +
  '<b>أول ' + failLines.length + ' خانة فشلت</b><ul style="margin:8px 0 0 0;padding-inline-start:18px;line-height:1.7;">' +
  li(failLines) + '</ul>' + (failMore ? '<div style="margin-top:6px;">… و' + failMore + ' خانة كمان.</div>' : '') + '</div>' : '') +
'<p style="margin:14px 0 0 0;line-height:1.9;">الرن الجاي هيعيد يسحب كل حاجة من أول وجديد. ' +
'لو المشكلة اتكررت، راجع صلاحية حساب جوجل المربوط بالأوتوميشن وحدود الاستخدام (Quota).</p>' +
'</div></div>';

return [{ json: {
  ok,
  problems, warnings,
  sheetValues: values,
  sheetRange: cfg.sheetTab + '!A1',
  writtenRows: values.length, writtenCols: width,
  quality: q,
  pageCheck: pageCheck,
  months, data: res.data, allMonths: res.allMonths, lastMonth: res.lastMonth,
  alertSubject, alertHtml, alertText,
  summaryLine: 'تغطية ' + Math.round(coverage * 1000) / 10 + '% • ' +
               'مسحوب: ' + ((q.tally || {}).ranked || 0) + ' • ' +
               'مفيش ظهور: ' + ((q.tally || {}).noData || 0) + ' • ' +
               'من الأرشيف: ' + (((q.tally || {}).fromArchive || 0) + ((q.tally || {}).archiveOnly || 0)) + ' • ' +
               'فاضية: ' + holes,
} }];

// يقرأ الشرائح الموجودة فعلياً دلوقتي من مخرجات Get Presentation
// لو العرض فاضي (0 شرائح) بيرجّع requests فاضية و hasSlides=false
// عشان نود الـ IF اللي بعده يتخطى الحذف بدل ما Google ترجّع 400
const cfg  = $('Config').first().json;
const pres = $input.first().json || {};

const ids = (pres.slides || []).map(s => s && s.objectId).filter(Boolean);

return [{ json: {
  presentationId: cfg.presentationId,
  deleteCount: ids.length,
  hasSlides: ids.length > 0,
  requests: ids.map(id => ({ deleteObject: { objectId: id } })),
} }];

const cfg = $('Config').first().json;
const res = $('Validate Data').first().json;
if (!res || !Array.isArray(res.data) || res.data.length === 0) {
  throw new Error('مفيش بيانات كلمات مفتاحية جاية من Validate Data — اتوقف قبل ما يبني عرض فاضي.');
}
const runId  = Date.now().toString(36) + Math.random().toString(36).slice(2, 7);

// ⚠️ الـ objectIds دي بتتولّد هنا مرة واحدة وبتتحقن في الداتا. يعني طلب
// batchUpdate اللي بيتبعت منها **مش idempotent**: لو اتبعت تاني بعد ما نجح،
// جوجل بيرد 400 "The object ID should be unique among all pages".
// عشان كده نود Create Slides ممنوع يكون عليه retryOnFail — n8n بيعيد النود
// كله من العنصر صفر، مش العنصر اللي فشل، فأول سلايد بيصطدم بنفسه.
// (فحص في validate.mjs بيرفض أي بناء يرجّع الـ retry ده.)

// عدد السلايدات في كل HTTP call. أقل عدد calls = فرصة أقل لخطأ عابر وضغط أقل
// على كوتة الكتابة. batchUpdate ذرّي: الـ call إما بيتطبّق كله أو مايتطبّقش
// خالص، فأي فشل مابيسيبش سلايد نص نص.
const SLIDES_PER_BATCH = 5;

// ============ الألوان — غيّرها من هنا ============
const BG   = { red: 0.949, green: 0.945, blue: 0.933 };   // خلفية 242,241,238
const INK  = { red: 0.078, green: 0.184, blue: 0.220 };   // نص 20,47,56
const BAR  = { red: 0.078, green: 0.184, blue: 0.220 };   // أعمدة 20,47,56
const POS  = { red: 0.078, green: 0.184, blue: 0.220 };   // لون الموضع 20,47,56
const IMP  = { red: 0.478, green: 0.561, blue: 0.600 };   // لون الظهور 122,143,153
// ============================================

const baseline = 335, chartLeft = 45, chartRight = 700, maxBarH = 150;

const AR = /[\u0600-\u06FF]/;
function isAr(t) { return AR.test(String(t)); }
function wrap(t) { return isAr(t) ? '\u202B' + t + '\u202C' : '\u202A' + t + '\u202C'; }
function dirOf(t) { return isAr(t) ? 'RIGHT_TO_LEFT' : 'LEFT_TO_RIGHT'; }
function pt(v) { return { magnitude: v, unit: 'PT' }; }
function elem(pageId, x, y, w, h) {
  return { pageObjectId: pageId, size: { width: pt(w), height: pt(h) },
           transform: { scaleX: 1, scaleY: 1, translateX: x, translateY: y, unit: 'PT' } };
}
function textBox(reqs, id, pageId, x, y, w, h, text, size, bold, align, color) {
  const t = String(text);
  reqs.push({ createShape: { objectId: id, shapeType: 'TEXT_BOX', elementProperties: elem(pageId, x, y, w, h) } });
  reqs.push({ insertText: { objectId: id, text: wrap(t), insertionIndex: 0 } });
  reqs.push({ updateTextStyle: { objectId: id, textRange: { type: 'ALL' },
    style: { foregroundColor: { opaqueColor: { rgbColor: color || INK } }, fontSize: pt(size), bold: !!bold, fontFamily: 'Calibri' },
    fields: 'foregroundColor,fontSize,bold,fontFamily' } });
  reqs.push({ updateParagraphStyle: { objectId: id, textRange: { type: 'ALL' },
    style: { alignment: align || 'CENTER', direction: dirOf(t) }, fields: 'alignment,direction' } });
  reqs.push({ updateShapeProperties: { objectId: id, shapeProperties: { contentAlignment: 'MIDDLE' }, fields: 'contentAlignment' } });
}
function rect(reqs, id, pageId, x, y, w, h, color) {
  reqs.push({ createShape: { objectId: id, shapeType: 'RECTANGLE', elementProperties: elem(pageId, x, y, w, h) } });
  reqs.push({ updateShapeProperties: { objectId: id,
    shapeProperties: { shapeBackgroundFill: { solidFill: { color: { rgbColor: color } } }, outline: { propertyState: 'NOT_RENDERED' } },
    fields: 'shapeBackgroundFill.solidFill.color,outline.propertyState' } });
}

// عدد مرات البحث: الأصل من ملف الإكسل (نود Keywords)، وأي قيمة مكتوبة يدويًا
// في نود "Search Volume" بتكسب — عشان تقدر تعدّل من غير ما ترجع للإكسل.
const svOverride = $('Search Volume').first().json || {};
function svText(d) {
  const manual = svOverride[d.keyword];
  const raw = (manual !== undefined && String(manual).trim() !== '') ? manual : d.sv;
  if (raw === undefined || raw === null || String(raw).trim() === '') return '—';
  const n = Number(String(raw).replace(/[^0-9.]/g, ''));
  return (isFinite(n) && n > 0) ? n.toLocaleString('en-US') : String(raw).trim();
}

const slides = [];
res.data.forEach((d, idx) => {
  const sid = 's' + runId + '_' + idx;
  const reqs = [];

  reqs.push({ createSlide: { objectId: sid, slideLayoutReference: { predefinedLayout: 'BLANK' } } });
  reqs.push({ updatePageProperties: { objectId: sid,
    pageProperties: { pageBackgroundFill: { solidFill: { color: { rgbColor: BG } } } },
    fields: 'pageBackgroundFill.solidFill.color' } });

  reqs.push({ createShape: { objectId: sid + '_fr', shapeType: 'RECTANGLE', elementProperties: elem(sid, 12, 12, 696, 381) } });
  reqs.push({ updateShapeProperties: { objectId: sid + '_fr',
    shapeProperties: { shapeBackgroundFill: { propertyState: 'NOT_RENDERED' },
      outline: { outlineFill: { solidFill: { color: { rgbColor: INK } } }, weight: pt(2), dashStyle: 'SOLID' } },
    fields: 'shapeBackgroundFill.propertyState,outline' } });

  rect(reqs, sid + '_lg', sid, 36, 32, 11, 11, BAR);
  textBox(reqs, sid + '_lgt', sid, 52, 25, 300, 24, d.group, 11, false, 'START');
  textBox(reqs, sid + '_t', sid, 55, 52, 610, 28, '«' + d.keyword + '»', 16, true, 'CENTER');

  const sub = 'عدد مرات البحث الشهري: ' + svText(d) + '   |   POS = الموضع   |   IMP = عدد الظهور';
  textBox(reqs, sid + '_s', sid, 55, 80, 610, 20, sub, 10, false, 'CENTER');

  // سطر نطاق القياس: بيقول الرقم ده اتقاس على إيه بالظبط، عشان أي حد يقدر
  // يفتح Search Console ويحط نفس الفلاتر ويطلع نفس الرقم.
  //   scope = 'page' → فلتر Query + Page في الواجهة
  //   scope = 'site' → فلتر Query لوحده
  const ltr = t => '\u2066' + String(t) + '\u2069';
  const scopeText = (d.scope === 'page' && d.page)
    ? 'الصفحة المستهدفة: ' + ltr(String(d.page).replace(/^https?:\/\//, ''))
    : 'كل صفحات الموقع للكلمة';
  const filters = 'نطاق القياس: ' + scopeText +
                  '   •   ' + d.country +
                  '   •   بحث الويب   •   بيانات نهائية';
  textBox(reqs, sid + '_f', sid, 55, 99, 610, 16, filters, 8, false, 'CENTER', IMP);

  const vals = d.positions;
  const imps = d.impressionsAll || [];
  const nums = vals.filter(v => v !== null && v !== undefined);
  const maxV = nums.length ? Math.max.apply(null, nums) : 1;
  const n = vals.length || 1;
  const slot = (chartRight - chartLeft) / n;
  const barW = Math.min(46, Math.max(10, slot * 0.7));

  // --- ضبط حجم الخط تلقائيًا بحيث النص ما يخرجش عن عرض العمود ---
  function fitSize(maxChars, boxW, maxS, minS) {
    const s = (boxW * 0.94) / (Math.max(1, maxChars) * 0.52);
    return Math.max(minS, Math.min(maxS, Math.round(s * 10) / 10));
  }
  let lblChars = 1;
  vals.forEach((v, i) => {
    if (v !== null && v !== undefined) {
      lblChars = Math.max(lblChars, ('POS ' + v).length, ('IMP ' + (imps[i] || 0)).length);
    }
  });
  const valFS = fitSize(lblChars, barW, 7.5, 4.5);

  const months = res.months || [];
  const capOf = mo => String((mo && (mo.caption || mo.label)) || '');
  const yrOf  = mo => String((mo && (mo.year || String(mo.key || '').split('-')[0])) || '');
  let capChars = 1, yrChars = 4;
  months.forEach(mo => {
    capOf(mo).split('\n').forEach(ln => { capChars = Math.max(capChars, ln.length); });
    yrChars = Math.max(yrChars, yrOf(mo).length);
  });
  const capFS = fitSize(capChars, slot, 7.5, 4);
  const yrFS  = fitSize(yrChars, slot, Math.max(4, capFS - 0.5), 4);

  vals.forEach((v, i) => {
    const cx = chartLeft + slot * i + slot / 2;
    if (v !== null && v !== undefined) {
      const h = Math.max(5, (v / (maxV * 1.2)) * maxBarH);
      rect(reqs, sid + '_b' + i, sid, cx - barW / 2, baseline - h, barW, h, BAR);
      textBox(reqs, sid + '_p' + i, sid, cx - slot / 2, baseline - h - 31, slot, 15,
              'POS ' + v, valFS, true, 'CENTER', POS);
      textBox(reqs, sid + '_v' + i, sid, cx - slot / 2, baseline - h - 18, slot, 15,
              'IMP ' + (imps[i] || 0), valFS, false, 'CENTER', IMP);
    }
    const mo = months[i] || {};
    const cap = capOf(mo);
    const multi = cap.indexOf('\n') !== -1;
    textBox(reqs, sid + '_m' + i, sid, cx - slot / 2, baseline + 3, slot, multi ? 30 : 14, cap, capFS, false, 'CENTER');
    const yr = yrOf(mo);
    if (yr) textBox(reqs, sid + '_y' + i, sid, cx - slot / 2, baseline + (multi ? 33 : 17), slot, 14, yr, yrFS, false, 'CENTER', IMP);
  });

  reqs.push({ createLine: { objectId: sid + '_ln', lineCategory: 'STRAIGHT',
    elementProperties: elem(sid, chartLeft - 8, baseline, chartRight - chartLeft + 16, 1) } });
  reqs.push({ updateLineProperties: { objectId: sid + '_ln',
    lineProperties: { lineFill: { solidFill: { color: { rgbColor: INK } } }, weight: pt(1.5) },
    fields: 'lineFill.solidFill.color,weight' } });

  slides.push({ keyword: d.keyword, requests: reqs });
});

// ---- تقسيم السلايدات على calls ----
const out = [];
for (let i = 0; i < slides.length; i += SLIDES_PER_BATCH) {
  const chunk = slides.slice(i, i + SLIDES_PER_BATCH);
  out.push({ json: {
    presentationId: cfg.presentationId,
    requests: chunk.reduce((a, s) => a.concat(s.requests), []),
    batchIndex: out.length,
    slidesInBatch: chunk.length,
    keywords: chunk.map(s => s.keyword),
    slidesExpected: slides.length,
  } });
}
out.forEach(o => { o.json.batchCount = out.length; });
return out;

// بيحسب أرقام الملخص اللي بتظهر في كروت الإيميل (تحسّن/تراجع/ثابت/متوسط التغير).
// النود ده كان بيبني كمان برومبت لتعليق AI — التعليق اتشال والحسابات فضلت.
const cfg = $('Config').first().json;
const res = $('Validate Data').first().json;
const m = res.months || [];
const li = m.length - 1, pi = m.length - 2;
const AR_MON = ['يناير','فبراير','مارس','أبريل','مايو','يونيو',
                'يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
function arMonth(mo) {
  if (!mo || !mo.key) return '';
  const parts = String(mo.key).split('-');
  return (AR_MON[Number(parts[1]) - 1] || parts[1]) + ' ' + parts[0];
}
function arWeek(mo) {
  if (!mo || !mo.startDate) return '';
  const s = new Date(mo.startDate + 'T00:00:00Z');
  const e = new Date(mo.endDate   + 'T00:00:00Z');
  const sm = AR_MON[s.getUTCMonth()], em = AR_MON[e.getUTCMonth()];
  const y  = e.getUTCFullYear();
  return sm === em
    ? 'أسبوع ' + s.getUTCDate() + ' – ' + e.getUTCDate() + ' ' + em + ' ' + y
    : 'أسبوع ' + s.getUTCDate() + ' ' + sm + ' – ' + e.getUTCDate() + ' ' + em + ' ' + y;
}
// نفس النود للتقريرين — الفرق بس في تسمية الفترة.
const periodLabel = cfg.cadence === 'weekly' ? arWeek : arMonth;
const lastLabel = m.length ? periodLabel(m[li]) : '';
const prevLabel = pi >= 0 ? periodLabel(m[pi]) : '';

let up = 0, down = 0, same = 0, gone = 0, fresh = 0, sum = 0, n = 0;
(res.data || []).forEach(d => {
  const last = d.positions[li], prev = pi >= 0 ? d.positions[pi] : null;
  if (prev === null && last !== null) { fresh++; return; }
  if (prev !== null && last === null) { gone++; return; }
  if (prev !== null && last !== null && prev !== 0) {
    const pct = Math.round(((prev - last) / prev) * 1000) / 10;
    sum += pct; n++;
    if (pct > 0) up++; else if (pct < 0) down++; else same++;
  }
});
const avg = n ? Math.round((sum / n) * 10) / 10 : 0;

// ---- حالة بناء العرض التقديمي ----
// Create Slides شغّال بـ continueRegularOutput (مايعملش retry لأن الـ objectIds
// بتتبعت من عندنا والطلب مش idempotent). فلازم نقرا ردوده بنفسنا ونقول في
// الإيميل لو العرض ما اكتملش، بدل ما نبعت لينك لعرض ناقص من غير ما حد يعرف.
const batches = $('Create Slides').all();
const plan    = $('Build Slide Batches').first().json || {};
let slidesDone = 0;
const slideErrors = [];
batches.forEach((b, i) => {
  const j = b.json || {};
  const err = j.error;
  if (err !== undefined && err !== null) {
    const txt = typeof err === 'string' ? err : (err.message || JSON.stringify(err));
    if (slideErrors.length < 10) slideErrors.push(String(txt).slice(0, 300));
    return;
  }
  const planned = $('Build Slide Batches').all()[i];
  slidesDone += Number((planned && planned.json.slidesInBatch) || 0);
});
const slidesExpected = Number(plan.slidesExpected || 0);
const slidesOk = slideErrors.length === 0 && (!slidesExpected || slidesDone === slidesExpected);

return [{ json: { up, down, same, fresh, gone, avg, lastLabel, prevLabel,
                  slidesOk, slidesDone, slidesExpected, slideErrors } }];

const cfg = $('Config').first().json;
const res = $('Validate Data').first().json;
const st  = $('Report Stats').first().json;

// ============ الألوان وحجم الخط — غيّرها من هنا ============
const BG    = '#f2f1ee';   // خلفية 242,241,238
const INK   = '#142f38';   // اللون الأساسي 20,47,56
const LINE  = '#d8d6d0';   // لون الحدود
const GREEN = '#1e7a34', RED = '#c0392b', GREY = '#7a7a7a';
const FS    = '14px';      // حجم الخط الموحّد لكل النصوص
// ========================================================

const AR_MON = ['يناير','فبراير','مارس','أبريل','مايو','يونيو',
                'يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
function arMonth(mo) {
  if (!mo || !mo.key) return '';
  const parts = String(mo.key).split('-');
  return (AR_MON[Number(parts[1]) - 1] || parts[1]) + ' ' + parts[0];
}
function arWeek(mo) {
  if (!mo || !mo.startDate) return '';
  const s = new Date(mo.startDate + 'T00:00:00Z');
  const e = new Date(mo.endDate   + 'T00:00:00Z');
  const sm = AR_MON[s.getUTCMonth()], em = AR_MON[e.getUTCMonth()];
  const y  = e.getUTCFullYear();
  return sm === em
    ? 'أسبوع ' + s.getUTCDate() + ' – ' + e.getUTCDate() + ' ' + em + ' ' + y
    : 'أسبوع ' + s.getUTCDate() + ' ' + sm + ' – ' + e.getUTCDate() + ' ' + em + ' ' + y;
}
// نفس النود للتقريرين — الفرق في تسمية الفترة وكلمة "أسبوعي/شهري" بس.
const WEEKLY = cfg.cadence === 'weekly';
const periodLabel = WEEKLY ? arWeek : arMonth;
const CAD_ADJ  = WEEKLY ? 'الأسبوعي' : 'الشهري';
const CAD_LAST = WEEKLY ? 'الأسبوع الأخير' : 'الشهر الأخير';
const withPrefix = (label) => (WEEKLY || !label) ? label : ('شهر ' + label);

const m  = res.months || [];
const li = m.length - 1, pi = m.length - 2;
const nowLabel  = m.length ? periodLabel(m[li]) : '';
const prevLabel = pi >= 0 ? periodLabel(m[pi]) : '';

const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// عدد مرات البحث: الأصل من الإكسل (نود Keywords)، وأي تعديل يدوي في نود
// "Search Volume" بيكسب.
const svOverride = $('Search Volume').first().json || {};
function svText(d) {
  const manual = svOverride[d.keyword];
  const raw = (manual !== undefined && String(manual).trim() !== '') ? manual : d.sv;
  if (raw === undefined || raw === null || String(raw).trim() === '') return '–';
  const n = Number(String(raw).replace(/[^0-9.]/g, ''));
  return (isFinite(n) && n > 0) ? n.toLocaleString('en-US') : String(raw).trim();
}

const rows = (res.data || []).map(d => {
  const last = d.positions[li], prev = pi >= 0 ? d.positions[pi] : null;
  let pct = null, color = GREY, arrow = '–', txt = '–';
  if (prev !== null && last !== null && prev !== 0) {
    pct = Math.round(((prev - last) / prev) * 1000) / 10;
    if (pct > 0)      { color = GREEN; arrow = '▲'; txt = '+' + pct + '%'; }
    else if (pct < 0) { color = RED;   arrow = '▼'; txt = pct + '%'; }
    else              { txt = '0%'; }
  } else if (prev === null && last !== null) { color = GREEN; arrow = '★'; txt = 'جديدة'; }
  else if (prev !== null && last === null)   { color = RED;   arrow = '✕'; txt = 'اختفت'; }
  // نجمة على الكلمات اللي رقمها على مستوى الموقع كله مش على صفحة محددة —
  // عشان اللي بيراجع في Search Console يعرف يحط الفلتر الصح.
  const siteWide = d.scope !== 'page';
  return { d, last, prev, pct, color, arrow, txt, sv: svText(d), siteWide };
});
rows.sort((a, b) => (b.pct === null ? -999 : b.pct) - (a.pct === null ? -999 : a.pct));

const td = 'padding:9px 10px;border-bottom:1px solid ' + LINE + ';font-size:' + FS + ';color:' + INK + ';';
const body = rows.map((r, i) => '<tr style="background:' + (i % 2 ? '#ffffff' : BG) + ';">' +
  '<td style="' + td + '">' + esc(r.d.keyword) + (r.siteWide ? ' <span style="color:' + GREY + ';">*</span>' : '') + '</td>' +
  '<td style="' + td + '">' + esc(r.d.section) + '</td>' +
  '<td style="' + td + 'text-align:center;">' + esc(r.d.country) + '</td>' +
  '<td style="' + td + 'text-align:center;">' + r.sv + '</td>' +
  '<td style="' + td + 'text-align:center;">' + (r.prev === null ? '–' : r.prev) + '</td>' +
  '<td style="' + td + 'text-align:center;font-weight:bold;">' + (r.last === null ? '–' : r.last) + '</td>' +
  '<td style="' + td + 'text-align:center;">' + (r.d.impressions || 0) + '</td>' +
