    (st.slidesExpected || 0) + '. الأرقام اللي فوق وفي الشيت صح ومكتملة. ' +
    'الرن الجاي بيمسح العرض ويبنيه من أول تلقائيًا.' +
    ((st.slideErrors || []).length ? ' السبب: ' + st.slideErrors[0] : '')
