  '<div style="margin-top:8px;font-size:12px;color:' + GREY + ';text-align:center;">' + esc(qualityNote) + '</div>' +
  (slidesNote ? '<div style="margin-top:12px;background:#fdf3f1;border:1px solid #e6b9b0;border-radius:6px;' +
    'padding:10px 14px;font-size:12px;line-height:1.8;color:' + INK + ';">' + esc(slidesNote) + '</div>' : '') +
  '<div style="margin-top:18px;background:' + BG + ';border:1px solid ' + LINE + ';border-radius:6px;padding:14px 16px;font-size:12px;line-height:1.9;">' +
    '<b>تحب تراجع أي رقم بنفسك على Search Console؟</b>' +
    '<ol style="margin:8px 0 0 0;padding-inline-start:18px;">' +
    verifySteps.map(t => '<li>' + esc(t) + '</li>').join('') + '</ol>' +
    '<div style="margin-top:8px;color:' + GREY + ';">' + esc(verifyNote) + '</div>' +
  '</div>' +
  (brokenLinks.length ? '<div style="margin-top:12px;background:#fdf3f1;border:1px solid #e6b9b0;' +
    'border-radius:6px;padding:10px 14px;font-size:12px;line-height:1.9;color:' + INK + ';">' +
    '<b>' + brokenLinks.length + ' رابط صفحة محتاج تصحيح</b> — الرابط اللي في ملف الكلمات مش ' +
    'الرابط النهائي للصفحة، وفلتر الصفحة في Search Console مش هيطابقه:<br>' +
    brokenLinks.slice(0, 8).map(function (x) {
      return '• ' + esc(x.keyword) + ' — ' + esc(x.note);
    }).join('<br>') + '</div>' : '') +
  (suspectPages.length ? '<div style="margin-top:12px;background:#fdf3f1;border:1px solid #e6b9b0;' +
    'border-radius:6px;padding:10px 14px;font-size:12px;line-height:1.9;color:' + INK + ';">' +
    '<b>' + suspectPages.length + ' كلمة رابطها محتاج مراجعة</b> — الصفحة المستهدفة ما ظهرتش ' +
    'عند جوجل ولا مرة رغم إن الكلمة ليها ترتيب بصفحات تانية. يعني الرابط اللي في ملف ' +
    'الكلمات غالبًا مش اللي جوجل مسجّله، والخانة بتطلع «مفيش ظهور» وهي مش صح:<br>' +
    suspectPages.slice(0, 8).map(function (x) {
      const sample = (x.samples || [])[0];
      return '• ' + esc(x.keyword) + (sample ? ' — جوجل شايف: ' + esc(sample.topPage) : '');
    }).join('<br>') + '</div>' : '') +
  (excluded.length ? '<div style="margin-top:12px;border:1px dashed ' + LINE + ';border-radius:6px;' +
    'padding:10px 14px;font-size:12px;line-height:1.9;color:' + GREY + ';">' +
    '<b style="color:' + INK + ';">كلمات خارج التقرير (' + excluded.length + ')</b> — ' +
    'مالهاش صفحة منشورة، فمفيش رابط نقيس عليه. أول ما تتنشر صفحتها ويتحط رابطها ' +
    'في ملف الكلمات، بتدخل التقرير أوتوماتيك:<br>' +
    excluded.map(function (e) { return esc(e.keyword); }).join(' • ') + '</div>' : '') +
'</div></div></div>';

// نسخة نصية — مهمة جدًا لتوصيل الإيميل: الرسائل اللي فيها HTML بس من غير
// نسخة نص عادي بتاخد سكور سبام أعلى عند جيميل وأوتلوك.
const textRows = rows.map(r =>
  '- ' + r.d.keyword + (r.siteWide ? ' *' : '') + ' (' + r.d.section + ') | بحث شهري: ' + r.sv +
  ' | السابق: ' + (r.prev === null ? '-' : r.prev) +
  ' | الحالي: ' + (r.last === null ? '-' : r.last) +
  ' | الظهور: ' + (r.d.impressions || 0) +
  ' | التغير: ' + r.txt);

const text = ['تقرير SEO ' + CAD_ADJ + ' — ' + cfg.company,
              withPrefix(nowLabel) + (prevLabel ? ' مقارنةً بـ' + withPrefix(prevLabel) : ''), '']
  .concat(ai.aiComment ? [ai.aiComment, ''] : (ai.aiOk === false ? ['⚠ ' + ai.aiNote, ''] : []))
  .concat(['تحسّن: ' + st.up + ' | تراجع: ' + st.down + ' | ثابت: ' + st.same +
           ' | متوسط التغير: ' + (st.avg > 0 ? '+' : '') + st.avg + '%', ''])
  .concat(textRows)
  .concat(['', 'الرقم الأقل = ترتيب أفضل.', qualityNote])
  .concat(slidesNote ? ['', '⚠ ' + slidesNote] : [])
  .concat(['', 'مراجعة الأرقام على Search Console:'])
  .concat(verifySteps.map((t, i) => (i + 1) + ') ' + t))
  .concat([verifyNote])
  .concat(brokenLinks.length
    ? ['', brokenLinks.length + ' رابط صفحة محتاج تصحيح:']
        .concat(brokenLinks.slice(0, 8).map(function (x) { return '- ' + x.keyword + ' — ' + x.note; }))
    : [])
  .concat(suspectPages.length
    ? ['', suspectPages.length + ' كلمة رابطها محتاج مراجعة (الصفحة ما ظهرتش عند جوجل ولا مرة):']
        .concat(suspectPages.slice(0, 8).map(function (x) { return '- ' + x.keyword; }))
    : [])
  .concat(excluded.length
    ? ['', 'كلمات خارج التقرير (' + excluded.length + ') — مالهاش صفحة منشورة:']
        .concat(excluded.map(function (e) { return '- ' + e.keyword; }))
    : [])
  .concat(['', 'التقرير الكامل بالسلايدز: ' + slides])
  .join('\n');

return [{ json: {
  emailHtml: html,
  emailText: text,
  periodLabel: nowLabel,
  subject: 'تقرير SEO ' + CAD_ADJ + ' — ' + cfg.company + ' — ' + withPrefix(nowLabel),
} }];

// بيقرأ رد سيرفر الـ SMTP الحقيقي بعد إرسال التقرير.
//
// المشكلة اللي بيحلها: نود Send Email بيعتبر الإرسال ناجح طالما السيرفر
// استلم الرسالة، حتى لو رفض بعض المستلمين (وده اللي بيحصل مع إيميلات جيميل
// لما السيرفر مش مسموح له يوصّل بره الدومين). فالرن بيبان أخضر والإيميل
// مش واصل. هنا بنقارن المستلمين المتوقعين بالمستلمين اللي السيرفر قبلهم
// فعلاً، وأي حد اترفض بنبعتله رسالة منفصلة وبنسجّل السبب.
const cfg  = $('Config').first().json;
const info = $input.first() ? ($input.first().json || {}) : {};

const norm = e => String(e || '').trim().toLowerCase();
const addrOf = (e) => {
  const s = String(e || '');
  const m = s.match(/<([^>]+)>/);
  return norm(m ? m[1] : s);
};

const expected = (cfg.mailAllList || []).map(norm).filter(Boolean);

const accepted = []
  .concat(Array.isArray(info.accepted) ? info.accepted : [])
  .map(addrOf).filter(Boolean);
const rejected = []
  .concat(Array.isArray(info.rejected) ? info.rejected : [])
  .concat(Array.isArray(info.pending)  ? info.pending  : [])
  .map(addrOf).filter(Boolean);

// الإرسال نفسه وقع (نود Send Report Email شغّال بـ continueRegularOutput):
// كل المستلمين محتاجين إعادة إرسال فردي، ولازم يوصل تنبيه.
const sendError = (info.error !== undefined && info.error !== null)
  ? (typeof info.error === 'string' ? info.error : (info.error.message || JSON.stringify(info.error))).slice(0, 300)
  : '';

// لو السيرفر مرجّعش قائمة accepted أصلاً مانفترضش الأسوأ ومانبعتش مرتين.
const knowsAccepted = accepted.length > 0 || rejected.length > 0;

const missing = sendError
  ? expected.slice()
  : (knowsAccepted ? expected.filter(e => accepted.indexOf(e) === -1) : []);

// ---- تشخيص: هل الرفض على أساس الدومين؟ ----
// لو كل اللي اترفض بره دومين المُرسِل وكل اللي اتقبل جواه، فدي مش مشكلة
// عنوان ولا مشكلة شبكة — دي **سياسة الناقل**: خدمة SMTP relay مضبوطة على
// "Only addresses in my domains". إعادة الإرسال على نفس السيرفر هتفشل بنفس
// الطريقة بالظبط، فمفيش أي فايدة من المحاولة.
const fromDomain = String(cfg.mailFromDomain || '').toLowerCase();
const domainOf = (e) => String(e).split('@')[1] || '';
const externalMissing = missing.filter(e => domainOf(e) !== fromDomain);
const internalMissing = missing.filter(e => domainOf(e) === fromDomain);
const acceptedExternal = accepted.filter(e => domainOf(e) !== fromDomain);

const relayBlocksExternal = knowsAccepted && !sendError &&
  externalMissing.length > 0 && internalMissing.length === 0 && acceptedExternal.length === 0;

// المستلمين اللي إعادة الإرسال ليها معنى معاهم: أي حد اترفض لسبب غير
// سياسة الدومين. لو السبب هو السياسة، مفيش إعادة إرسال — فيه تشخيص.
const retryable = relayBlocksExternal ? [] : missing;

const relayDiagnosis = relayBlocksExternal
  ? ('الناقل قبل كل المستلمين على دومين ' + fromDomain + ' ورفض كل اللي بره الدومين (' +
     externalMissing.join(', ') + '). ده مش خطأ في العناوين ولا في الأوتوميشن — ده إعداد ' +
     'خدمة SMTP relay مضبوط على «Only addresses in my domains». ' +
     'الحل: Google Admin console ← Apps ← Google Workspace ← Gmail ← Routing ← SMTP relay ' +
     'service ← غيّر Allowed recipients لـ «Any addresses». ' +
     'إعادة الإرسال على نفس السيرفر هتفشل بنفس الطريقة فمابنعملهاش.')
  : '';

const base = {
  expected,
  accepted,
  rejected,
  missing,
  externalMissing,
  relayBlocksExternal,
  relayDiagnosis,
  knowsAccepted,
  sendError,
  messageId: info.messageId || '',
  smtpResponse: sendError || String(info.response || '').slice(0, 300),
  envelopeFrom: (info.envelope && info.envelope.from) || '',
  subject: $('Build Email').first().json.subject,
};

if (!retryable.length) {
  return [{ json: Object.assign({ __resend: false, resendCount: 0 }, base) }];
}

return retryable.map((recipient, i) => ({ json: Object.assign({
  __resend: true,
  recipient,
  resendIndex: i,
  resendCount: retryable.length,
}, base) }));

// بيلمّ نتايج الإرسال الفردي ويبني تنبيه بحالة التوصيل لكل مستلم.
const cfg   = $('Config').first().json;
const audit = $('Delivery Audit').first().json || {};
const tries = $input.all();

const norm = e => String(e || '').trim().toLowerCase();
const addrOf = (e) => {
  const s = String(e || '');
  const m = s.match(/<([^>]+)>/);
  return norm(m ? m[1] : s);
};

// الربط بـ pairedItem زي باقي النودات — الترتيب لوحده مش ضمان.
const auditItems = $('Delivery Audit').all();
function srcIndex(item, fallbackIndex) {
  const p = item ? item.pairedItem : undefined;
  if (typeof p === 'number') return p;
  if (p && typeof p.item === 'number') return p.item;
  if (Array.isArray(p) && p.length && p[0] && typeof p[0].item === 'number') return p[0].item;
  return fallbackIndex;
}

// النود ده بيوصله ٣ أشكال دخل مختلفة، ولازم يفرّق بينهم:
//   1) ردود إعادة الإرسال عبر SMTP     → فيها accepted/rejected
//   2) ردود الإرسال البديل عبر Gmail API → فيها id أو error
//   3) عنصر عابر من غير أي إرسال        → مفيش لا ده ولا ده
// الخلط بينهم كان بيخلي التقرير يقول "ما وصلش" على رن كل حاجة فيه تمام.
const isSmtpReply  = (j) => Array.isArray(j.accepted) || Array.isArray(j.rejected);
const isGmailReply = (j) => j.labelIds !== undefined || (j.id !== undefined && j.raw === undefined);
const sendReplies  = tries.filter((t) => {
  const j = (t && t.json) || {};
  return (isSmtpReply(j) || isGmailReply(j)) && j.__resend === undefined && j.__gmailSend === undefined;
});
const noResend = sendReplies.length === 0;
const viaGmail = sendReplies.length > 0 && sendReplies.every((t) => isGmailReply(t.json || {}));

/* المسار البديل بيجيب اسم المستلم من نود التجهيز مش من رد جوجل */
let gmailPlan = [];
try { gmailPlan = $('Build Gmail Fallback').all(); } catch (e) { gmailPlan = []; }

const rows = [];
if (!noResend) sendReplies.forEach((item, i) => {
  const j = item.json || {};
  const idx = srcIndex(item, i);
  const src = viaGmail
    ? (gmailPlan[idx] || gmailPlan[i] || {})
    : (auditItems[idx] || auditItems[i] || {});
  const target = norm((src.json || {}).recipient || '');
  const err = (j.error !== undefined && j.error !== null)
    ? (typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error))).slice(0, 300)
    : '';
  const accepted = (Array.isArray(j.accepted) ? j.accepted : []).map(addrOf);
  rows.push({
    recipient: target,
    ok: viaGmail ? !err : (!err && accepted.indexOf(target) !== -1),
    error: err,
    response: viaGmail ? ('Gmail API' + (j.id ? ' · ' + j.id : '')) : String(j.response || '').slice(0, 200),
    via: viaGmail ? 'gmail-api' : 'smtp',
  });
});

const failed = rows.filter(r => !r.ok);
const fixed  = rows.filter(r => r.ok);

// سياسة الناقل: الرفض على أساس الدومين. مفيش إعادة إرسال ليها معنى هنا،
// والتقرير لازم يقول السبب والحل بدل ما يقول "ما وصلش" ويسيب الناس تخمّن.
const relayBlocked = !!audit.relayBlocksExternal;
const blockedList = audit.externalMissing || [];

const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const line = r => (r.ok ? 'وصل بعد إعادة الإرسال' : 'ما وصلش') + ' — ' + r.recipient +
                  (r.error ? ' — ' + r.error : (r.response ? ' — ' + r.response : ''));

const text = [
  'تقرير حالة توصيل إيميل SEO — ' + cfg.company,
  '',
  'الموضوع: ' + (audit.subject || ''),
  'المستلمين المتوقعين: ' + (audit.expected || []).join(', '),
  'اللي السيرفر قبلهم في الإرسال الأول: ' + ((audit.accepted || []).join(', ') || 'مفيش'),
  'اللي اترفضوا أو ماتأكدوش: ' + ((audit.missing || []).join(', ') || 'مفيش'),
  'رد سيرفر SMTP: ' + (audit.smtpResponse || '—'),
  '',
  relayBlocked && noResend ? 'إعادة الإرسال: اتوقفت عن قصد — السبب مش عنوان غلط.'
    : viaGmail ? 'اتبعت عبر المسار البديل (Gmail API) للمستلمين اللي SMTP رفضهم:'
    : 'نتيجة إعادة الإرسال الفردي:',
].concat((relayBlocked && noResend)
   ? ['', 'المستلمين اللي ما وصلهمش: ' + blockedList.join(', '), '', audit.relayDiagnosis]
   : rows.map(r => '- ' + line(r)))
 .concat((!relayBlocked && failed.length) ? [
   '',
   'المستلمين دول لسه ما وصلهمش الإيميل. ده معناه إن سيرفر SMTP نفسه رافض',
   'يوصّل لبره الدومين، أو إن الرسالة بتتحجب عند المستلم. الحل في الإعدادات',
   'مش في الأوتوميشن — راجع ملف EMAIL-DELIVERABILITY.md.',
 ] : (relayBlocked ? [] : (noResend
     ? ['', 'كل المستلمين قبلهم السيرفر من أول مرة.']
     : ['', 'كل المستلمين وصلهم الإيميل بعد إعادة الإرسال الفردي.'])))
 .join('\n');

const html =
'<div style="font-family:Calibri,Arial,sans-serif;direction:rtl;text-align:right;background:#f2f1ee;padding:24px;color:#142f38;font-size:14px;">' +
'<div style="max-width:700px;margin:0 auto;background:#ffffff;border:1px solid #d8d6d0;border-radius:10px;padding:22px;">' +
'<h3 style="margin:0 0 12px 0;font-size:16px;">حالة توصيل إيميل التقرير — ' + esc(cfg.company) + '</h3>' +
((relayBlocked && noResend)
  ? '<div style="background:#fdf3f1;border:1px solid #e6b9b0;border-radius:6px;padding:12px 16px;margin-bottom:14px;line-height:1.9;">' +
    '<b>الناقل رافض يوصّل بره الدومين.</b><br>' +
    'المستلمين اللي ما وصلهمش: ' + esc(blockedList.join(', ')) + '<br><br>' +
    esc(audit.relayDiagnosis) + '</div>'
  : '<p style="line-height:1.9;margin:0 0 14px 0;">الإرسال الأول ما وصلش لكل المستلمين، فأعدنا الإرسال لكل واحد لوحده. ' +
    'دي النتيجة النهائية:</p>') +
(rows.length ? '<table width="100%" cellspacing="0" cellpadding="0" style="border-collapse:collapse;border:1px solid #d8d6d0;">' +
'<tr><th style="padding:10px;background:#142f38;color:#fff;text-align:right;">المستلم</th>' +
'<th style="padding:10px;background:#142f38;color:#fff;text-align:center;">الحالة</th>' +
'<th style="padding:10px;background:#142f38;color:#fff;text-align:right;">رد السيرفر</th></tr>' +
rows.map((r, i) => '<tr style="background:' + (i % 2 ? '#ffffff' : '#f2f1ee') + ';">' +
  '<td style="padding:9px 10px;border-bottom:1px solid #d8d6d0;">' + esc(r.recipient) + '</td>' +
  '<td style="padding:9px 10px;border-bottom:1px solid #d8d6d0;text-align:center;color:' +
    (r.ok ? '#1e7a34' : '#c0392b') + ';font-weight:bold;">' + (r.ok ? 'وصل' : 'ما وصلش') + '</td>' +
  '<td style="padding:9px 10px;border-bottom:1px solid #d8d6d0;">' + esc(r.error || r.response || '—') + '</td></tr>').join('') +
'</table>' : '') +
'<p style="margin:14px 0 0 0;line-height:1.9;"><b>رد سيرفر SMTP في الإرسال الأول:</b> ' + esc(audit.smtpResponse || '—') + '</p>' +
((relayBlocked && noResend) ? ''
  : failed.length
  ? '<p style="margin:10px 0 0 0;line-height:1.9;">لسه فيه ' + failed.length + ' مستلم ما وصلهوش. ' +
    'المشكلة في إعدادات السيرفر مش في الأوتوميشن — راجع ملف <b>docs/EMAIL.md</b> ' +
    '(صلاحية الإرسال الخارجي + SPF و DKIM و DMARC).</p>'
  : '<p style="margin:10px 0 0 0;line-height:1.9;color:#1e7a34;">' +
    (noResend ? 'كل المستلمين قبلهم السيرفر من أول مرة.' : 'كل المستلمين وصلهم الإيميل بعد إعادة الإرسال الفردي.') + '</p>') +
'</div></div>';

return [{ json: {
  deliveryRows: rows,
  stillFailing: failed.map(r => r.recipient),
  recovered: fixed.map(r => r.recipient),
  relayBlocked,
  blockedRecipients: blockedList,
  viaGmail,
  alertSubject: ((relayBlocked && noResend) ? 'الناقل رافض يوصّل بره الدومين — ' :
                 failed.length ? 'إيميل التقرير ما وصلش لكل المستلمين — ' :
                 noResend ? 'حالة توصيل إيميل التقرير — ' :
                 'إيميل التقرير اتصلّح بعد إعادة الإرسال — ') + cfg.company,
  /* مافيش تنبيه إلا لما يكون فيه حاجة تتقال فعلاً */
  __silent: (noResend && !relayBlocked) || (viaGmail && failed.length === 0),
  alertHtml: html,
  alertText: text,
} }];

// بيحوّل "مقدرناش نوصل لـ Search Console" لسبب محدد وخطوة واضحة.
//
// بيقرا حاجتين:
//   1) رد طلب الموقع المحدد في Config  (نود Verify GSC Access)
//   2) قائمة المواقع اللي الحساب المربوط شايفها فعلاً (نود List GSC Sites)
// ومن الاتنين دول بيعرف: التوكن واقع؟ ولا الحساب مالوش صلاحية؟ ولا الرابط
// المكتوب في Config مش مطابق لشكل الموقع المسجّل في جوجل؟
const cfg    = $('Config').first().json;
const verify = $('Verify GSC Access').first().json || {};
const listed = $input.first() ? ($input.first().json || {}) : {};

function errText(e) {
  if (e === undefined || e === null) return '';
  if (typeof e === 'string') return e;
  if (e.message) return String(e.message);
  try { return JSON.stringify(e); } catch (x) { return String(e); }
}

const verifyErr = errText(verify.error);
const listErr   = errText(listed.error);
const blob      = (verifyErr + ' ' + listErr);

// المواقع اللي الحساب شايفها
const entries = Array.isArray(listed.siteEntry) ? listed.siteEntry : [];
const sites = entries.map(e => ({
  url: String(e.siteUrl || ''),
  level: String(e.permissionLevel || ''),
}));

const want = String(cfg.siteUrl || '');
const norm = (u) => String(u || '').trim().toLowerCase()
  .replace(/^sc-domain:/, '').replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/+$/, '');
const wantN = norm(want);

const exact  = sites.find(s => s.url === want);
const sameHost = sites.filter(s => norm(s.url) === wantN && s.url !== want);
const readOnly = sites.filter(s => /^(siteUnverifiedUser|siteRestrictedUser)$/.test(s.level));

// ---------------- تحديد السبب ----------------
let cause, action, severity = 'blocked';

if (/invalid_grant|invalid_token|Token has been expired|revoked|unauthorized_client/i.test(blob)
    || /\b401\b/.test(blob)) {
  cause = 'صلاحية حساب جوجل المربوط بالأوتوميشن انتهت أو اتسحبت. '
        + 'ده بيحصل لما الباسورد يتغيّر، أو حد يشيل صلاحية n8n من إعدادات الحساب، '
        + 'أو التوكن يقعد فترة طويلة من غير استخدام.';
  action = 'افتح n8n ← Credentials ← "' + cfg.googleCredentialName + '" ← اضغط Reconnect وسجّل دخول '
         + 'بحساب جوجل اللي عنده صلاحية على الموقع، وبعدين شغّل الأوتوميشن يدويًا من Manual Trigger.';
} else if (sameHost.length) {
  cause = 'الرابط المكتوب في إعدادات الأوتوميشن مش مطابق لشكل الموقع المسجّل في '
        + 'Search Console. جوجل بيعتبرهم موقعين مختلفين تمامًا حتى لو نفس الدومين.';
  action = 'غيّر SITE_URL في نود Config من "' + want + '" لـ "' + sameHost[0].url + '" بالظبط '
         + '(انسخه زي ما هو من الجدول تحت).';
} else if (sites.length && !exact) {
  cause = 'الحساب المربوط بالأوتوميشن شغّال تمام، بس الموقع "' + want + '" مش موجود '
        + 'في المواقع اللي الحساب ده عنده صلاحية عليها.';
  action = 'يا إما تضيف الحساب ده كمستخدم على الموقع في Search Console '
         + '(الإعدادات ← المستخدمون والأذونات ← إضافة مستخدم)، يا إما تظبط SITE_URL في '
         + 'نود Config على واحد من المواقع الموجودة في الجدول تحت.';
} else if (/\b403\b|does not have sufficient permission|insufficientPermissions|forbidden/i.test(blob)) {
  cause = 'الحساب المربوط متصل بس مالوش صلاحية على الموقع ده في Search Console.';
  action = 'من Search Console: الإعدادات ← المستخدمون والأذونات ← إضافة مستخدم، '
         + 'وضيف حساب جوجل المربوط بالأوتوميشن بصلاحية "كامل" أو "مقيّد".';
} else if (/\b404\b|notFound/i.test(blob) && !sites.length) {
  cause = 'جوجل بيقول إن الموقع ده مش موجود عنده، والأوتوميشن كمان مقدرش يجيب قائمة '
        + 'المواقع — غالبًا الصلاحية واقعة أو الـ API مش مفعّل على المشروع.';
  action = 'راجع كريدنشيال جوجل في n8n (Reconnect)، واتأكد إن Search Console API مفعّل '
         + 'في Google Cloud Console على المشروع اللي عامل منه الـ OAuth.';
} else if (/\b429\b|quota|rateLimit/i.test(blob)) {
  cause = 'جوجل رفض الطلب مؤقتًا بسبب تجاوز حد الاستخدام.';
  action = 'مفيش حاجة تتعمل — شغّل الأوتوميشن تاني بعد شوية. لو اتكررت كل مرة، '
         + 'راجع حصة Search Console API في Google Cloud Console.';
  severity = 'temporary';
} else if (/ETIMEDOUT|ECONNRESET|ENOTFOUND|socket hang up|timeout|\b5\d\d\b/i.test(blob)) {
  cause = 'الاتصال بجوجل نفسه فشل (شبكة أو عطل مؤقت عند جوجل).';
  action = 'شغّل الأوتوميشن تاني من Manual Trigger. لو فضل بيفشل، راجع اتصال سيرفر n8n بالإنترنت.';
  severity = 'temporary';
} else if (!verifyErr && !verify.siteUrl) {
  cause = 'جوجل رد على الطلب بس الرد مالهوش الشكل المتوقع (مفيش siteUrl في الرد).';
  action = 'ابعت لقطة من مخرجات نود "Verify GSC Access" — التفاصيل الخام تحت في الإيميل ده.';
} else {
  cause = 'مقدرناش نحدد السبب أوتوماتيك من رد جوجل.';
  action = 'راجع رسالة الخطأ الخام تحت، وابدأ بعمل Reconnect لكريدنشيال جوجل في n8n.';
}

// ---------------- بناء الإيميل ----------------
const esc = t => String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const LEVEL_AR = {
  siteOwner: 'مالك', siteFullUser: 'صلاحية كاملة',
  siteRestrictedUser: 'صلاحية مقيّدة', siteUnverifiedUser: 'غير مُتحقّق',
};

const sitesHtml = sites.length
  ? '<table width="100%" cellspacing="0" cellpadding="0" style="border-collapse:collapse;border:1px solid #d8d6d0;margin-top:8px;">'
    + '<tr><th style="padding:9px 10px;background:#142f38;color:#fff;text-align:right;font-size:13px;">الموقع كما هو مسجّل في جوجل</th>'
    + '<th style="padding:9px 10px;background:#142f38;color:#fff;text-align:center;font-size:13px;">الصلاحية</th></tr>'
    + sites.map((s, i) => '<tr style="background:' + (i % 2 ? '#ffffff' : '#f2f1ee') + ';">'
      + '<td style="padding:8px 10px;border-bottom:1px solid #d8d6d0;font-family:monospace;direction:ltr;text-align:left;">'
      + esc(s.url) + '</td>'
      + '<td style="padding:8px 10px;border-bottom:1px solid #d8d6d0;text-align:center;">'
      + esc(LEVEL_AR[s.level] || s.level) + '</td></tr>').join('')
    + '</table>'
  : '<p style="margin:8px 0 0 0;color:#c0392b;">مقدرناش نجيب قائمة المواقع كمان — '
    + 'ده بيرجّح إن المشكلة في صلاحية الحساب نفسه مش في الموقع.</p>';

const raw = [
  verifyErr ? 'رد فحص الموقع: ' + verifyErr : '',
  listErr   ? 'رد قائمة المواقع: ' + listErr : '',
].filter(Boolean).join('\n') || 'مفيش رسالة خطأ صريحة من جوجل.';

const subject = 'تقرير SEO ' + (cfg.cadence === 'weekly' ? 'الأسبوعي' : 'الشهري')
              + ' لم يُرسل — ' + cfg.company + ' — مشكلة في الوصول لـ Search Console';

const text = [
  'تقرير SEO ما اتبعتش — ' + cfg.company,
  '',
  'إيه اللي حصل:',
  cause,
  '',
  'إيه اللي تعمله:',
  action,
  '',
  'الموقع المطلوب في الإعدادات: ' + want,
  'المواقع اللي الحساب المربوط شايفها (' + sites.length + '):',
].concat(sites.length
    ? sites.map(s => '  - ' + s.url + '   [' + (LEVEL_AR[s.level] || s.level) + ']')
    : ['  (مقدرناش نجيبها)'])
 .concat([
  '',
  'رسالة جوجل الخام:',
  raw,
  '',
  'الشيت والعرض التقديمي ما اتلمسوش خالص — مفيش أي بيانات اتغيرت.',
 ]).join('\n');

const html =
'<div style="font-family:Calibri,Arial,sans-serif;direction:rtl;text-align:right;background:#f2f1ee;padding:24px;color:#142f38;font-size:14px;">'
+ '<div style="max-width:700px;margin:0 auto;background:#ffffff;border:1px solid #d8d6d0;border-radius:10px;padding:22px;">'
+ '<h3 style="margin:0 0 4px 0;font-size:16px;">تقرير SEO ما اتبعتش — ' + esc(cfg.company) + '</h3>'
+ '<div style="color:#7a7a7a;margin-bottom:16px;">مشكلة في الوصول لـ Google Search Console</div>'

+ '<div style="background:#f2f1ee;border-right:4px solid #c0392b;border-radius:4px;padding:12px 16px;margin-bottom:14px;">'
+ '<b>إيه اللي حصل بالظبط</b>'
+ '<p style="margin:6px 0 0 0;line-height:1.9;">' + esc(cause) + '</p></div>'

+ '<div style="background:#f2f1ee;border-right:4px solid #1e7a34;border-radius:4px;padding:12px 16px;margin-bottom:14px;">'
+ '<b>إيه اللي تعمله</b>'
+ '<p style="margin:6px 0 0 0;line-height:1.9;">' + esc(action) + '</p></div>'

+ '<p style="margin:0 0 4px 0;"><b>الموقع المطلوب في إعدادات الأوتوميشن:</b></p>'
+ '<div style="font-family:monospace;direction:ltr;text-align:left;background:#f2f1ee;border:1px solid #d8d6d0;'
+ 'border-radius:4px;padding:8px 10px;margin-bottom:14px;">' + esc(want) + '</div>'

+ '<p style="margin:0 0 4px 0;"><b>المواقع اللي الحساب المربوط شايفها فعلاً:</b></p>'
+ sitesHtml

+ '<p style="margin:16px 0 4px 0;"><b>رسالة جوجل الخام (للفني):</b></p>'
+ '<div style="font-family:monospace;direction:ltr;text-align:left;background:#f2f1ee;border:1px solid #d8d6d0;'
+ 'border-radius:4px;padding:8px 10px;white-space:pre-wrap;word-break:break-word;font-size:12px;">'
+ esc(raw) + '</div>'

+ '<p style="margin:16px 0 0 0;line-height:1.9;background:#f2f1ee;border-radius:4px;padding:10px 14px;">'
+ '<b>الشيت والعرض التقديمي ما اتلمسوش خالص</b> — مفيش أي بيانات اتغيرت ولا اتمسحت. '
+ 'بعد ما تظبط السبب، شغّل الأوتوميشن يدويًا من زرار Manual Trigger.</p>'

+ '</div></div>';

return [{ json: {
  alertSubject: subject, alertHtml: html, alertText: text,
  diagnosis: { cause, action, severity, want, sites, raw, readOnly: readOnly.length },
} }];

// بيجهّز طلب فحص لكل رابط صفحة مستهدفة — مرة واحدة لكل رابط فريد.
//
// ليه الفحص ده موجود: فلتر الصفحة في Search Console بيطابق **الرابط الكانوني**
// بالحرف. لو الرابط اللي في ملف الكلمات بيعمل تحويل (redirect) أو الصفحة معلنة
// كانوني مختلف، جوجل ما بيرجّعش الصفحة دي فالخانة بتطلع "مفيش ظهور" — والرقم
// ده غلط، ومحدش بيشك فيه لأن الرابط بيفتح عادي لما تجربه بإيدك.
const kws = $('Keywords').first().json.keywords || [];

const seen = {};
const urls = [];
kws.forEach(function (k) {
  const u = String(k.page || '').trim();
  if (!u || !/^https?:\/\//i.test(u) || seen[u]) return;
  seen[u] = 1;
  urls.push(u);
});

if (!urls.length) {
  return [{ json: { __skipPageCheck: true, url: '', pageCount: 0 } }];
}

return urls.map(function (u, i) {
  return { json: { __skipPageCheck: false, url: u, pageIndex: i, pageCount: urls.length } };
});

// بيقرأ ردود فحص الروابط ويحكم على كل رابط.
//
// الحكم بيدخل بوابة الجودة وبيظهر في الإيميل. مش بيوقف الرن لوحده —
// رابط مكسور مش معناه إن باقي الأرقام غلط — لكنه بيمنع إن رقم مبني على
// رابط مش كانوني يعدّي وهو محسوب "مفيش ظهور".
const prep = $('Prep Page Checks').all();
const kws  = $('Keywords').first().json.keywords || [];
const res  = $input.all();

function normUrl(u) {
  let s = String(u == null ? '' : u);
  for (let i = 0; i < 2; i++) {
    try { const d = decodeURIComponent(s); if (d === s) break; s = d; } catch (e) { break; }
  }
  s = s.trim().toLowerCase();
  s = s.replace(/[#?].*$/, '');
  s = s.replace(/^https?:\/\//, '').replace(/^www\./, '');
  s = s.replace(/\/index\.(html?|php)$/, '/');
  s = s.replace(/\/+$/, '');
  return s;
}

const skipped = !!(prep[0] && prep[0].json.__skipPageCheck);
const byUrl = {};

if (!skipped) {
  prep.forEach(function (p, i) {
    const url = p.json.url;
    const r = (res[i] && res[i].json) || {};
    const err = (r.error !== undefined && r.error !== null)
      ? (typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error))).slice(0, 200)
      : '';
    const status = Number(r.statusCode || r.status || 0);
    const finalUrl = String((r.headers && (r.headers.location || r.headers.Location)) || r.url || url);
    const body = typeof r.body === 'string' ? r.body : '';

    let canonical = '';
    const m = body.slice(0, 200000).match(/<link[^>]+rel=["']?canonical["']?[^>]*>/i);
    if (m) {
      const h = m[0].match(/href=["']([^"']+)["']/i);
      if (h) {
        canonical = h[1].trim();
        if (canonical.indexOf('/') === 0) {
          const base = url.match(/^(https?:\/\/[^/]+)/);
          if (base) canonical = base[1] + canonical;
        }
      }
    }

    let verdict = 'ok', note = 'الرابط مطابق للكانوني';
    if (err)                       { verdict = 'unreachable'; note = 'مقدرناش نوصل للصفحة: ' + err; }
    else if (status === 0)         { verdict = 'unreachable'; note = 'مفيش رد من الصفحة'; }
    else if (status >= 500)        { verdict = 'server-error'; note = 'HTTP ' + status; }
    else if (status === 404 || status === 410) { verdict = 'broken'; note = 'HTTP ' + status + ' — الصفحة مش موجودة'; }
    else if (status >= 300 && status < 400)    { verdict = 'redirected'; note = 'HTTP ' + status + ' — بيحوّل إلى: ' + finalUrl; }
    else if (canonical && normUrl(canonical) !== normUrl(url)) {
      verdict = 'canonical'; note = 'الصفحة معلنة كانوني مختلف: ' + canonical;
    }
    byUrl[url] = { url: url, status: status, canonical: canonical, suggested: canonical || finalUrl,
                   verdict: verdict, note: note };
  });
}

/* كل استبعاد أو شبهة بتترجم لكلمات بأسمائها — مش لعدد مجرّد */
const problems = [];
kws.forEach(function (k) {
  const r = byUrl[k.page];
  if (!r || r.verdict === 'ok') return;
  problems.push({ keyword: k.keyword, page: k.page, verdict: r.verdict,
                  note: r.note, suggested: r.suggested });
});

const tally = {};
Object.keys(byUrl).forEach(function (u) { tally[byUrl[u].verdict] = (tally[byUrl[u].verdict] || 0) + 1; });

/* مهم: لو كل الروابط اترفضت بنفس الشكل فالمشكلة في الشبكة اللي n8n شغال
 * عليها، مش في الروابط. إعلان ٢٧ رابط سليم "مكسور" أسوأ من السكوت. */
const total = Object.keys(byUrl).length;
const allFailed = total > 1 && (tally.unreachable || 0) + (tally['server-error'] || 0) === total;

return [{ json: {
  pageCheck: {
    skipped: skipped,
    checked: total,
    tally: tally,
    problems: allFailed ? [] : problems,
    networkBlocked: allFailed,
    results: Object.keys(byUrl).map(function (u) { return byUrl[u]; }),
  },
} }];

// مسار بديل للإرسال: Gmail API بدل SMTP.
//
// ليه موجود: لما خدمة SMTP relay تكون مضبوطة على "Only addresses in my
// domains" بترفض كل مستلم خارجي، وإعادة المحاولة على نفس السيرفر بتفشل
// بنفس الطريقة. Gmail API بيبعت من صندوق الحساب المربوط مباشرة ومابيعديش
// على خدمة الترحيل أصلًا، فالقيد ده مالوش وجود عنده.
//
// بيستخدم نفس كريدنشيال جوجل المربوط بـ Search Console و Sheets — محتاج بس
// إضافة صلاحية gmail.send عليه، مش كريدنشيال جديد.
const cfg   = $('Config').first().json;
const audit = $('Delivery Audit').first().json || {};
const mail  = $('Build Email').first().json || {};

const targets = (audit.externalMissing || []).length
  ? audit.externalMissing
  : (audit.missing || []);

if (!cfg.gmailFallback || !targets.length) {
  return [{ json: { __gmailSend: false, gmailTargets: [], gmailSkipReason:
    !cfg.gmailFallback ? 'المسار البديل مقفول في Config (MAIL_GMAIL_FALLBACK)' : 'مفيش مستلم محتاج إرسال بديل' } }];
}

/* ---- بناء رسالة RFC822 ---- */
// العناوين اللي فيها حروف عربية لازم تتشفّر (RFC 2047)، وإلا السيرفر بيرفض
// الرسالة أو بيطلّع رموز مكسورة عند المستلم.
const b64 = (s) => Buffer.from(String(s), 'utf8').toString('base64');
const encHeader = (s) => /^[\x20-\x7E]*$/.test(String(s))
  ? String(s)
  : '=?UTF-8?B?' + b64(s) + '?=';

const fromName = String(cfg.mailFromDisplay || cfg.mailFrom).replace(/^"(.*)"\s*<.*$/, '$1');
const from = /</.test(cfg.mailFromDisplay || '')
  ? encHeader(fromName) + ' <' + cfg.mailFrom + '>'
  : cfg.mailFrom;

const boundary = 'alojan_' + Date.now().toString(36);

function buildRaw(recipient) {
  const lines = [
    'From: ' + from,
    'To: ' + recipient,
    'Reply-To: ' + (cfg.mailReplyTo || cfg.mailFrom),
    'Subject: ' + encHeader(mail.subject || ''),
    'MIME-Version: 1.0',
    'Content-Type: multipart/alternative; boundary="' + boundary + '"',
    '',
    '--' + boundary,
    'Content-Type: text/plain; charset="UTF-8"',
    'Content-Transfer-Encoding: base64',
    '',
    b64(mail.emailText || '').replace(/(.{76})/g, '$1\r\n'),
    '',
    '--' + boundary,
    'Content-Type: text/html; charset="UTF-8"',
    'Content-Transfer-Encoding: base64',
    '',
    b64(mail.emailHtml || '').replace(/(.{76})/g, '$1\r\n'),
    '',
    '--' + boundary + '--',
    '',
  ];
  // Gmail API بياخد base64url (بـ - و _ بدل + و /) ومن غير padding
  return Buffer.from(lines.join('\r\n'), 'utf8').toString('base64')
    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

return targets.map((recipient, i) => ({ json: {
  __gmailSend: true,
  recipient,
  gmailIndex: i,
  gmailTargets: targets,
  raw: buildRaw(recipient),
} }));

// تعليق تحليلي قصير من نموذج لغوي — كان موجود عند الروضة بس.
//
// ⚠️ الخطر اللي بيحرسه النود ده: النموذج بيكتب **نص حر عن أرقام**، ودي بالظبط
// المنطقة اللي بيتولد فيها رقم مختلق («ارتفعت التحويلات ٤٠٪») من غير ما حد
// يشك — لأنه جوه فقرة تبدو معقولة جنب جدول أرقامه صح.
//
// فالقاعدة هنا: **أي رقم في التعليق لازم يكون له أصل في الأرقام المحسوبة.**
// الأرقام المسموحة: إحصائيات الملخص، ومواضع الكلمات ونسب تغيّرها، والسنوات.
// لو النموذج جاب رقم من عنده، التعليق كله يتشال ويتسجّل السبب — تعليق ناقص
// أرخص من رقم مختلق في تقرير بيتبعت لعميل.
const cfg = $('Config').first().json;
const res = $('Validate Data').first().json;
const st  = $('Report Stats').first().json;

if (!cfg.aiComment) {
  return [{ json: { __ai: false, aiSkipReason: 'التعليق التحليلي مقفول لهذا العميل', prompt: '' } }];
}

const m = res.months || [];
const li = m.length - 1, pi = m.length - 2;

/* ---- الأرقام المسموح للنموذج يذكرها ---- */
const allowed = {};
const allow = (v) => {
  const n = Number(v);
  if (isFinite(n)) allowed[String(Math.abs(n))] = true;
};
[st.up, st.down, st.same, st.fresh, st.gone, st.avg, (res.data || []).length].forEach(allow);
allow(new Date().getFullYear());
(m || []).forEach((mo) => { String(mo.key || '').split(/[-W]/).forEach(allow); });

const lines = [];
(res.data || []).forEach((d) => {
  const last = d.positions[li], prev = pi >= 0 ? d.positions[pi] : null;
  let pct = null, state;
  if (prev === null && last !== null)      { state = 'جديدة'; }
  else if (prev !== null && last === null) { state = 'اختفت'; }
  else if (prev !== null && last !== null && prev !== 0) {
    pct = Math.round(((prev - last) / prev) * 1000) / 10;
    state = pct > 0 ? 'تحسّن' : (pct < 0 ? 'تراجع' : 'ثابت');
  } else state = 'لا بيانات';
  allow(last); allow(prev); allow(pct); allow(d.impressions);
  lines.push('- ' + d.keyword + ' | السابق: ' + (prev === null ? '-' : prev) +
             ' | الحالي: ' + (last === null ? '-' : last) +
             ' | التغير: ' + (pct === null ? '-' : (pct > 0 ? '+' : '') + pct + '%') + ' | ' + state);
});

const label = (mo) => String((mo && (mo.label || mo.key)) || '');
const prompt =
'اكتب فقرتين قصيرتين فقط (بحد أقصى 90 كلمة) كتعليق تحليلي على تقرير SEO لشركة "' + cfg.company + '".\n' +
'ابدأ بالضبط بـ: "تحية طيبة ' + cfg.manager + ' المدير،"\n' +
'الرقم الأقل في الترتيب أفضل. النسبة الموجبة تحسّن والسالبة تراجع.\n' +
'لا تكتب جداول ولا قوائم ولا Markdown ولا رموز # أو *. نص عادي فقط. ولا تذكر أي روابط.\n' +
'**ممنوع تمامًا تذكر أي رقم غير الأرقام الموجودة في البيانات تحت.** لا تحسب نسبًا جديدة ' +
'ولا تتوقع أرقامًا مستقبلية ولا تقدّر شيئًا. لو محتاج تقول حاجة من غير رقم، قولها بالكلام.\n' +
'الفقرة الأولى: خلاصة الفترة. الفقرة الثانية: توصية عملية واحدة.\n\n' +
label(m[li]) + (pi >= 0 ? ' مقابل ' + label(m[pi]) : '') + '\n' +
'تحسّن: ' + st.up + ' | تراجع: ' + st.down + ' | ثابت: ' + st.same +
' | جديدة: ' + st.fresh + ' | اختفت: ' + st.gone + '\n' +
'متوسط التغير: ' + (st.avg > 0 ? '+' : '') + st.avg + '%\n\n' + lines.join('\n');

return [{ json: {
  __ai: true,
  prompt: prompt,
  allowedNumbers: Object.keys(allowed),
} }];

// بيقرأ رد النموذج ويتحقق من كل رقم فيه قبل ما يدخل الإيميل.
//
// أي رقم مالوش أصل في الأرقام المحسوبة = التعليق كله يتشال. مش بنصلّح
// التعليق ولا بنشيل الرقم وسيبه — لأن الجملة اللي فيها رقم مختلق معناها
// كله مشكوك فيه، مش رقمها بس.
const prep = $('Build AI Comment').first().json || {};
const raw  = $input.first() ? ($input.first().json || {}) : {};

if (!prep.__ai) {
  return [{ json: { aiComment: '', aiOk: true, aiSkipped: true, aiNote: prep.aiSkipReason || '' } }];
}

/* قراءة الرد من أي مزوّد (DeepSeek/OpenAI أو Anthropic) */
function readText(r) {
  if (!r) return '';
  if (typeof r === 'string') return r;
  if (r.choices && r.choices[0] && r.choices[0].message) {
    const c = r.choices[0].message.content;
    return typeof c === 'string' ? c : '';
  }
  if (Array.isArray(r.content)) {
    return r.content.filter(b => b && b.type === 'text').map(b => b.text).join('\n');
  }
  return '';
}

const err = (raw.error !== undefined && raw.error !== null)
  ? (typeof raw.error === 'string' ? raw.error : (raw.error.message || JSON.stringify(raw.error))).slice(0, 250)
  : '';
let text = String(readText(raw) || '').trim();

if (err || !text) {
  return [{ json: { aiComment: '', aiOk: false, aiSkipped: true,
                    aiNote: err ? ('نداء التعليق فشل: ' + err) : 'النموذج رجّع نص فاضي' } }];
}

/* تنظيف: ممنوع Markdown ولا روابط — لو ظهرت نشيلها */
text = text.replace(/https?:\/\/\S+/g, '').replace(/[#*`_>]/g, '').replace(/\n{3,}/g, '\n\n').trim();

/* ---- التحقق: كل رقم في النص له أصل؟ ---- */
const AR_DIGITS = { '٠':'0','١':'1','٢':'2','٣':'3','٤':'4','٥':'5','٦':'6','٧':'7','٨':'8','٩':'9' };
const norm = text.replace(/[٠-٩]/g, ch => AR_DIGITS[ch] || ch).replace(/٫/g, '.').replace(/٪/g, '%');

const allowed = {};
(prep.allowedNumbers || []).forEach(v => { allowed[String(v)] = true; });

const found = norm.match(/\d+(?:\.\d+)?/g) || [];
const orphans = [];
found.forEach(v => {
  const n = Number(v);
  if (!isFinite(n)) return;
  if (allowed[String(Math.abs(n))]) return;
  if (Number.isInteger(n) && n <= 12) return;    /* أعداد صغيرة وصفية */
  if (orphans.indexOf(v) === -1) orphans.push(v);
});

if (orphans.length) {
  return [{ json: {
    aiComment: '', aiOk: false, aiSkipped: false,
    aiOrphans: orphans,
    aiRejectedText: text.slice(0, 600),
    aiNote: 'التعليق اتشال: فيه ' + orphans.length + ' رقم (' + orphans.join('، ') +
            ') مالوش أصل في الأرقام المحسوبة. رقم مختلق في فقرة رأي أخطر من غياب التعليق.',
  } }];
}

return [{ json: { aiComment: text, aiOk: true, aiSkipped: false, aiNote: '' } }];
